import Foundation

/// Item text from `ItemLoreTable` (generated by `scripts/generate-item-lore.py`).
/// PokéAPI has no pt or ru text, so those languages read the English entry.
enum ItemLore {
    static func text(_ slug: String, in language: AppLanguage) -> String {
        guard let entry = ItemLoreTable.entries[slug] else { return "" }
        return entry.texts[language.rawValue] ?? entry.texts["en"] ?? ""
    }

    /// Scout tickets are counted by `scout.<pool>` inventory keys, so they share one table entry with a `{pool}` placeholder.
    static let scoutTicketSlug = "app-scout-ticket"

    static func isAppOriginal(_ slug: String) -> Bool { ItemLoreTable.entries[slug]?.appOriginal ?? false }

    static func isAppOriginal(_ slug: String, in language: AppLanguage) -> Bool {
        ItemLoreTable.entries[slug]?.appOriginalLanguages.contains(language.rawValue) ?? false
    }

    /// nil for app-original items and for languages PokéAPI has no item names for.
    static func officialName(_ slug: String, in language: AppLanguage) -> String? {
        ItemLoreTable.entries[slug]?.names[language.rawValue]
    }
}

extension ItemKind {
    /// Key into `ItemLoreTable`: the PokéAPI item name, or `app-mint` for the one item the games do not have.
    var loreSlug: String {
        switch self {
        case .rareCandy: return "rare-candy"
        case .mint: return "app-mint"
        case .shinyCharm: return "shiny-charm"
        case .linkingCord: return "linking-cord"
        default: return heldItemSlug ?? evolutionItemName ?? rawValue
        }
    }
}

extension MegaStone {
    var loreSlug: String { slug }
}
